def pivot_index(nums):
    n = len(nums)
    for i in range(n):
        left_sum = sum(nums[:i])                                  # resums the left side from scratch every time
        right_sum = sum(nums[i + 1:])                                # resums the right side from scratch every time
        if left_sum == right_sum:
            return i
    return -1


if __name__ == "__main__":
    print(pivot_index([1, 7, 3, 6, 5, 6]))

