import java.util.*;

public class Main {
    int pivotIndex(int[] nums) {
        int n = nums.length;
        for (int i = 0; i < n; i++) {
            int leftSum = 0;
            for (int j = 0; j < i; j++) leftSum += nums[j];                // resums the left side from scratch every time
            int rightSum = 0;
            for (int j = i + 1; j < n; j++) rightSum += nums[j];             // resums the right side from scratch every time
            if (leftSum == rightSum) return i;
        }
        return -1;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        System.out.println(solution.pivotIndex(new int[]{1, 7, 3, 6, 5, 6}));
    }
}

